cJSON *button_to_json(uint8_t cls, uint8_t id, std::span<const uint8_t> body)
{
    switch (cls) {
    case fr::wire::kClsCmd:
        switch (id) {
        case Button::kCmdInject:
            return json_of(decode_button_inject_args(body));
        }
        break;
    case fr::wire::kClsResult:
        switch (id) {
        case Button::kCmdInject:
            return json_empty(body);
        }
        break;
    case fr::wire::kClsEvent:
        switch (id) {
        case Button::kEventDown:
            return json_of(decode_button_down(body));
        case Button::kEventUp:
            return json_of(decode_button_up(body));
        case Button::kEventClick:
            return json_of(decode_button_click(body));
        case Button::kEventLongPress:
            return json_of(decode_button_long_press(body));
        }
        break;
    case fr::wire::kClsState:
        switch (id) {
        case Button::kPropPressed: {
            const auto v = decode_button_pressed_state(body);
            if (!v) {
                return nullptr;
            }
            cJSON *o = cJSON_CreateObject();
            return finish(o, o != nullptr && add(o, "pressed", json_bool(*v)));
        }
        }
        break;
    default:
        break;
    }
    return nullptr;
}

